959	        &mut self,
960	        workspace: &Entity<Workspace>,
961	        window: &mut Window,
962	        cx: &mut Context<Self>,
963	    ) {
964	        let project = workspace.read(cx).project().clone();
965	        if project.read(cx).is_via_collab() {
966	            return;
967	        }
968	
969	        cx.subscribe_in(
970	            &project,
971	            window,
972	            |this, project, event, _window, cx| match event {
973	                ProjectEvent::WorktreeAdded(_)
974	                | ProjectEvent::WorktreeRemoved(_)
975	                | ProjectEvent::WorktreeOrderChanged => {
976	                    this.schedule_update_entries(false, cx);
977	                }
978	                ProjectEvent::WorktreePathsChanged { old_worktree_paths } => {
979	                    this.move_entry_paths(project, old_worktree_paths, cx);
980	                    this.schedule_update_entries(false, cx);
981	                }
982	                _ => {}
983	            },
984	        )
985	        .detach();
986	
987	        let git_store = workspace.read(cx).project().read(cx).git_store().clone();
988	        cx.subscribe_in(
989	            &git_store,
990	            window,
991	            |this, _, event: &project::git_store::GitStoreEvent, _window, cx| {
992	                if matches!(
993	                    event,
994	                    project::git_store::GitStoreEvent::RepositoryUpdated(
995	                        _,
996	                        project::git_store::RepositoryEvent::GitWorktreeListChanged
997	                            | project::git_store::RepositoryEvent::HeadChanged,
998	                        _,
999	                    )
1000	                ) {
1001	                    this.schedule_update_entries(false, cx);
1002	                }
1003	            },
1004	        )
1005	        .detach();
1006	
1007	        cx.subscribe_in(
1008	            workspace,
1009	            window,
1010	            move |this, workspace, event: &workspace::Event, window, cx| {
